eval("\nmodule.exports = {\n    en: {\n        aboutpilots: {\n            header: `10 Interesting Facts About Pilots`,\n            text: `There are probably no people who would deny the importance of aviation\n          in today’s fast moving world. The question is how much do we really\n          know about aviation and pilots ? Undoubtedly, there are countless\n          interesting and surprising facts about pilots which may surprise you.\n          That is the reason why we have chosen to come up with the list of the\n          most astonishing facts about pilots. Who knows, maybe after reading\n          this article you will be able to add some new facts about aviation and\n          pilot profession to your knowledge pool.`,\n            read: `Read More`\n        }\n    },\n    ka: {\n        aboutpilots: {\n            header: `10 საინტერესო ფაქტი პილოტების შესახებ`,\n            text: `ალბათ არ არსებობს ხალხი, ვინც უარყოფს ავიაციის მნიშვნელობას\n           დღევანდელ სწრაფად მოძრავ სამყაროში. საკითხავია, რეალურად რამდენს ვაკეთებთ\n           იცით ავიაციის და პილოტების შესახებ? უდავოა, უთვალავია\n          საინტერესო და გასაკვირი ფაქტები მფრინავების შესახებ, რომლებიც შეიძლება გაგიკვირდეთ.\n         ეს არის მიზეზი, რის გამოც ჩვენ ავირჩიეთ შეგვექმნა სია\n         ყველაზე გასაოცარი ფაქტები მფრინავების შესახებ. ვინ იცის, იქნებ წაკითხვის შემდეგ\n         ამ სტატიაში თქვენ შეძლებთ დაამატოთ რამდენიმე ახალი ფაქტი ავიაციის შესახებ და\n          პილოტის პროფესია თქვენი ცოდნის ფონდში.`,\n            read: `ნახვა`\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/views/Blog page/About Pilots/aboutpilots.module.js\n");

