eval("\nmodule.exports = {\n    en: {\n        FlightCancellationCompensationHowMuch: {\n            _h1: `How much compensation should you get for flight delay?`,\n            _h2: `For flights covered by EU law EC 261, any delay longer than three hours and any cancellation without at least 14 days prior entitles you to a financial compensation.`,\n            _h3: `The amount of flight compensation you receive depends on the duration of the delay and the distance of your flight. For details see the chart:`\n        }\n    },\n    ka: {\n        FlightCancellationCompensationHowMuch: {\n            _h1: `რამდენი კომპენსაცია უნდა მიიღოთ ფრენის დაგვიანებისთვის?`,\n            _h2: `ევროკავშირის EC 261 კანონით გათვალისწინებული ფრენებისთვის, სამ საათზე მეტი შეფერხება და ნებისმიერი გაუქმება მინიმუმ 14 დღით ადრე მოგცემთ უფლებას მიიღოთ ფინანსური კომპენსაცია.`,\n            _h3: `ფრენის კომპენსაციის ოდენობა დამოკიდებულია დაგვიანების ხანგრძლივობაზე და თქვენი ფრენის მანძილზე. დეტალებისთვის იხილეთ სქემა:`\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/views/FlightCancellation/CompensationHowMuch/CompensationHowMuch.module.js\n");

